/* Multiverse by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero { max-width:none; padding:24px; border-bottom:1px solid #ffffff33; }
.ip-hero .ip-banner { height:160px; }
.ip-title { text-transform:uppercase; letter-spacing:.12em; font-size:clamp(var(--pager-title-min-size), calc(1rem + 3vw), var(--pager-title-size)); font-weight:var(--pager-title-font-weight); }
.ip-navigation { border:0; }
.ip-block { max-width:none; padding:16px 0; }
.ip-block .block-heading { padding-inline:24px; font-size:1rem; text-transform:uppercase; letter-spacing:.1em; }
.ip-photo::after { display:none; }
@media(max-width:760px) { .ip-hero { padding:24px 20px; } .ip-block { padding-inline:0; } }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
